"""SOUND-3 provenance reconciliation and documentary handoff; no audio edits."""
from pathlib import Path
import hashlib,json,zipfile,datetime

R=Path(__file__).resolve().parents[3]
O=R/'Art/Audio/Real'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run():
    index=json.loads((O/'sources/index.json').read_text())
    edits=json.loads((O/'edits.json').read_text())
    metrics=json.loads((O/'metrics.json').read_text())
    opened=json.loads((O/'review/opened.json').read_text())
    assert len(index)==25 and len(edits['files'])==71 and len(opened['sheets'])==27
    for r in index:
        assert r['clean'] and r['scan_returncode']==0 and 'found no threats' in r['scan_stdout']
        assert sha(R/r['local'])==r['sha256']
        assert r['license']=='CC0-1.0'
    def source(p):
        for r in index:
            original=R/r['local']
            if p==original:return r,r['original_filename']
            if original.suffix=='.zip' and p.is_relative_to(original.parent/'extracted'):
                member=p.relative_to(original.parent/'extracted').as_posix()
                with zipfile.ZipFile(original) as z:assert hashlib.sha256(z.read(member)).hexdigest()==sha(p)
                return r,r['original_filename']+' / '+member
        raise ValueError(p)
    lines=['# SOUND-3 recording licence ledger','','71 edited outputs; every source page explicitly lists CC0. Commercial use is allowed under [CC0 1.0](https://creativecommons.org/publicdomain/zero/1.0/). Source-page snapshots and full Defender output are retained in sources/. Source claims are credited as supplied, not independently proven authorship.','','Every row below belongs to one output file. Layered outputs have multiple source rows. Original archive members are verified byte-for-byte against their scanned archive. edits.json records exact cuts, filters, fades, placements, gains and source/output SHA256. No audio was fetched from YouTube or through a login.','','## Credits and limitations','','Baby animals: compiler Technopeasant labels the pack CC0 and credits AGFX (43380), felix.blume (391026, 134348), foxen10 (149024), Foleyhaven (618483), lolamadeus (196251), AntumDeluge (583142), swiftoid (182509), jsbarrett (200333) on Freesound. The page does not map Bark.ogg/Meow.ogg to individual recordists; retain the full credit list rather than invent a mapping. These originals were downloaded directly from the CC0 OpenGameArt pack, not Freesound.','','Peludo requests a reference to their itch.io page; the asset page does not give an explicit itch URL. Credit Peludo and the linked source page; resolve their requested optional link before publishing credits.','','Water field recordings: RandomMind = Vistula river; jasinski = Alki beach. transitking water takes were scanned but not used. Unused downloads remain in the source inventory, not this output ledger.','','## Per-output sources','','| Output | Source page / direct download | Original download / archive member | Author | Licence | Defender result / receipt |','|---|---|---|---|---|---|']
    used=set()
    for e in edits['files']:
        assert sha(O/e['file'])==e['sha256']
        unique={}
        for layer in e['layers']:
            p=R/layer['source'];assert sha(p)==layer['source_sha256']
            r,member=source(p);unique[str(p)]=(r,member);used.add(r['local'])
        for r,member in unique.values():
            receipt='sources/'+r['source_page'].rsplit('/',1)[1]+'--'+r['original_filename']+'.scan.json'
            assert (O/receipt).exists()
            lines.append(f"| [{e['file']}]({e['file']}) | [page]({r['source_page']}) · [download]({r['download_url']}) | {member} | {r['author']} | [{r['license']}]({r['license_url']}) | exit0; found no threats; [receipt]({receipt}) |")
    (O/'LICENSES.md').write_text('\n'.join(lines)+'\n')
    for s in opened['sheets']:assert sha(O/s['file'])==s['sha256']
    groups={}
    for e in edits['files']:
        family=Path(e['file']).stem.rsplit('_',1)[0];groups.setdefault(family,[]).append(e)
    byfile={m['file']:m for m in metrics['files']}
    report=['# SOUND-3 — real recording candidates','','Owner: Codex 2 (WSL CLI). 2026-10-25. Artist delivery complete with the five authorised skips below. Listening, contextual suitability, native mixing and integration remain pending with Claude/Mo. No game audio has been replaced in Assets.','','## Delivery','','66 mono SFX WAVs: 22 cue families with three edited variants each. Five stereo 30-second ambience WAVs. All are 44.1kHz/16-bit PCM, using the existing filename convention. 25 original audio/zip downloads passed Windows Defender before extraction/decoding. '+str(len(used))+' downloaded originals/archives contribute to outputs. The remaining downloads are retained candidates, not used implicitly.','','[LICENSES.md](LICENSES.md) supplies per-output URLs, originals, authors, CC0 licences and clean scan receipts. [edits.json](edits.json) is the cut/layer/hash manifest. [metrics.json](metrics.json) supplies independently decoded output measurements. [review/opened.json](review/opened.json) records all 27 sheets actually opened and visual observations.','','## Coverage and Foley choices','','These are recording-based candidates, not an auditory approval. Real physical materials stand in for game actions: bicycle spokes for reel/hauler, household bells for buoy bells, metal contact for crab claws, cloth for net handling/stitching, pumpkin cutting for gutting, and pot/cloth/water for pot deployment. No pitch-shifted or synthesized animal/horn substitutes were made.','','Three variants means three WAV edits, not necessarily three separate performances. DogBark and Meow each use ONE original call with small EQ/gain differences. Reel, Creak, Coins and some UI edits reuse overlapping or identical cuts with mastering differences; their hashes differ, but this does not prove audible variety. Review repeated playback before accepting them.','','All five beds are water-only candidates. HarbourDay/Dusk use different actual Vistula-river excerpts. OpenSea/Skerries/LighthouseRock layer short Alki-beach wave recordings over different river excerpts. They do not supply actual coastal wind, location-specific harbour activity, wildlife or horn calls. A convincing open-sea/location identity is unverified; replace these candidates if listening rejects the river-water character.','','| Family | WAVs | Description | Measured LUFS range | Longest duration |','|---|---|---|---|---|']
    for family,items in groups.items():
        mm=[byfile[e['file']] for e in items]
        report.append(f"| {family} | {len(items)} | {items[0]['description']} | {min(m['integrated_lufs'] for m in mm):.2f} to {max(m['integrated_lufs'] for m in mm):.2f} | {max(m['duration_seconds'] for m in mm):.3f}s |")
    report+=['','## Five skipped families / candidates for Mo','','No Gull, SealBark, Puffin, Horn or Foghorn WAVs were created (15 requested variants absent). The brief explicitly permits skips instead of synthesis. The following are research candidates, not approved or downloaded replacement sources. Login-gated Freesound originals were skipped; account access and preview workarounds were not used.','','| Missing family | Best lead found | Why absent |','|---|---|---|','| Gull | [speakingmusic / 586831](https://freesound.org/people/speakingmusic/sounds/586831/), CC0 Pacific seagulls | Original download requires login. The OpenGameArt solo-seagull candidate explicitly originated from YouTube and was rejected. |','| Horn | [felix.blume / 162350](https://freesound.org/people/felix.blume/sounds/162350/), CC0 Istanbul cruise-ship horns | Original download requires login; evaluate scale/timbre for a small boat. |','| Foghorn | [SoundsExciting / 543897](https://freesound.org/people/SoundsExciting/sounds/543897/), CC0 DeTour Reef lighthouse | Original download requires login. |','| SealBark | [designerschoice marine-animal pack](https://freesound.org/people/designerschoice/packs/43408/) | Research lead only: sea-lion material is not a verified grey-seal match; individual licence/download not cleared. No suitable allowed-source grey-seal recording found. |','| Puffin | [designerschoice bird pack](https://freesound.org/people/designerschoice/packs/43450/) | Weak research lead only: taxonomy mentions puffin but no suitable individual CC0 puffin file was verified; pack is labelled Attribution. No qualified candidate found. |','','Other rejected sources: OpenGameArt chain-winch-sounds is explicitly synthesized; water-splashes is CC-BY; cartoon foghorn imitation is not an actual horn recording. No rejected source contributes to output. Bell dings/chimes and equipment-click downloads were scanned but not selected.','','## Processing and technical verification','','Only recorded input audio was used. Operations: crop/downmix/resample, 35–45Hz high-pass and per-cue low-pass, fades, DC correction, real-recording layering, transient gain automation and loudness normalisation. No generated noise, oscillator, saturation or pitch shift. Several high-crest-factor sources needed repeated gain-envelope passes to reach the target without clipping; this can alter transients and requires listening for pumping/dulling. Short UI is 100–120ms.','','Loudness uses the existing SOUND1 measurement convention: BS.1770 K-weighting/gating and short-clip zero-padding to 400ms. This is a consistent game-pack target measurement, not a claim about perceived loudness. General cues centre -24LUFS; UI near -32; bells/animals -27; Stitch -29; PotDrop -25; water -28 except dusk -30. Variants use up to 0.2LU offsets (Click 0.6LU lower).','','Decoded checks PASS for all 71 files: correct format/channel count, target error under 1 LU, per-family spread under 2 LU, sample and estimated 4x true peak at or below -3dBFS, DC under 0.0007, faded one-shot endpoints. All five loops are exactly 1,323,000 stereo frames/30s with matched seam values/slopes within 1 PCM and nonzero live seam RMS. 100ms recorded-water overlap and 2ms endpoint correction were used; numerical continuity does not establish inaudible repetition.','','Winch 8Hz/12Hz overlap at gain 0.65 peaks '+f"{metrics['winch_overlap']['8Hz']['gain065_sum_peak_dbfs']:.2f}/ {metrics['winch_overlap']['12Hz']['gain065_sum_peak_dbfs']:.2f}"+'dBFS. This verifies that isolated overlap fixture only, not the native mixer with all other voices.','','All 27 original waveform/spectrogram PNGs were opened and visually inspected. They show bounded waveforms, tapered one-shots, bell/animal spectral structure and continuous water beds. Later small water impacts are visible in Splash/NetSlap/PotDrop; listening must determine whether they fit each action. No audio playback/listening or native game test was performed.','','## Reproduce / handoff','','Run from project root with ffmpeg available and the existing numpy/scipy/Pillow environment:','','```sh','python3 -B Art/Source/Audio/acquire3.py','# Acquisition rechecks source pages; existing clean receipts are reused only if hashes match.','/home/mo/.venvs/catchline-ui/bin/python -B Art/Source/Audio/build3.py','/home/mo/.venvs/catchline-ui/bin/python -B Art/Source/Audio/check3.py','# Reopen changed sheets before renewing opened.json.','python3 -B Art/Source/Audio/document3.py','```','','Acquisition accepts only direct approved OpenGameArt CC0 audio/zip. Each download is quarantined in a source folder and scanned with MpCmdRun before Python zipfile extraction or ffmpeg decode. Archives are inspected for forbidden executable extensions, traversal, absolute paths and symlinks; only audio/licence text is extracted. Sources/index.json retains all 25 clean receipts, scan commands, stdout and SHA256. Source-page HTML snapshots are documentary data and were not executed.','','Claude/Mo next: listen to candidates at intended mix levels, especially foley substitutions, reused variations, processed impacts and water beds; decide skipped-family sourcing and whether the beds fit each location. Then integrate approved files under lead ownership. Do not treat technical PASS or this delivery as auditory approval. No Unity, Assets, git, player-save or watchdog changes. CHEST-ART-1 remains held with its earlier reference work intact.']
    (O/'REPORT.md').write_text('\n'.join(report)+'\n')
    paths=[p for p in O.rglob('*') if p.is_file() and p.name!='verification-receipt.json']
    for name in ['acquire3.py','build3.py','check3.py','document3.py','acquire3.log','build3.log','check3.log','dsp.py','analyze.py']:
        paths.append(R/'Art/Source/Audio'/name)
    paths+= [R/r['local'] for r in index]
    receipt={'task':'SOUND-3','owner':'Codex 2 (WSL CLI)','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'technical_result':'PASS','listening':'NOT PERFORMED','native_integration':'NOT PERFORMED','download_count':len(index),'wav_count':71,'opened_sheet_count':27,'missing_families':edits['missing_families'],'files':[{'file':str(p.relative_to(R)),'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(set(paths))]}
    (O/'verification-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
    print('SOUND3 PROVENANCE PASS',len(index),'clean originals;',len(used),'used;71 output hashes;27 opened sheet hashes;',len(receipt['files']),'receipt files')
if __name__=='__main__':run()
